-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := '1b933361-d0aa-4350-8a1c-fa849844863f';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Organising Data So It Works', 'Most spreadsheet pain is not a formula problem. It is a layout problem that shows up later as a formula problem. This module fixes the layout first.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Turning a List into a Real Table', 'A short, focused look at Excel''s Table feature — what it does to a plain range and why it is worth converting. Just over 3 minutes.', 'https://www.youtube.com/watch?v=iroIA8_3soo', 1,
      array['Lay out data as one record per row and one field per column', 'Convert a plain range into a proper Excel Table', 'Recognise why merged cells and blank spacer rows break sorting and formulas'],
      'A spreadsheet Excel can actually work with looks like a table: one header row at the top, then one record per row underneath, with each column holding exactly one kind of value.

A sales sheet has a Date column, a Customer column and an Amount column — not a single "Details" column with "12 Mar, Achieng, 4,500" crammed into it. If you ever want to sort by date, total by customer, or filter to one month, each of those has to be its own column. You cannot add that structure later without retyping.

Three habits that look tidy and quietly cause damage:

MERGED CELLS. Merging makes a heading look centred and makes the range unsortable. Excel no longer knows which row a merged value belongs to, so sorting either refuses outright or scrambles the data. If you want the centred look without the damage, use Format Cells → Alignment → Center Across Selection instead.

BLANK ROWS AND COLUMNS USED AS SPACING. Excel works out how far your data extends by looking for the first blank. A spacer row in the middle means sorting, filtering and AutoSum all silently stop there and quietly ignore everything below it. No warning, just a wrong total.

TWO TABLES ON ONE SHEET, side by side. They share rows, so sorting one reorders the other. Give each table its own sheet.

There is a fourth trap worth knowing: NUMBERS STORED AS TEXT. A column of amounts typed with a leading apostrophe, or pasted from a web page, will not add up. If SUM returns 0 over cells that obviously contain numbers, they are text. The tell is that they sit left-aligned in the cell instead of right-aligned.

Converting your range to a real Table (Ctrl+T) is the shortcut to most of this: it gives you a proper header row, filter buttons, and a range that grows automatically as you add rows.',
      'Take any list you already have — expenses, stock, contacts — and rebuild it as a clean table: one header row, one record per row, one kind of value per column, no merged cells and no blank spacer rows. Convert it with Ctrl+T. Then test your work by sorting on one column. If each row stays internally consistent, with the right amount still beside the right name, the layout is sound. If anything scrambles, you still have a merge or a blank row in there.',
      '[{"question":"Your sales sheet won''t sort by date. What is the most likely cause?","options":["A merged cell or a blank spacer row inside the range","The file has grown too large for Excel to sort","Dates cannot be used as a sort key","You need to write a formula before sorting"],"correct_index":0},{"question":"A column clearly shows numbers, but SUM over it returns 0. What is happening?","options":["The values are stored as text rather than as numbers","SUM only works on whole numbers","The column is hidden from calculations","The cells must be formatted as currency first"],"correct_index":0}]'::jsonb),
    (v_m1, 'Sorting Without Scrambling Your Data', 'How sorting actually works on a range, including sorting by more than one column. About 4 and a half minutes.', 'https://www.youtube.com/watch?v=Ep5q1cUhQas', 2,
      array['Sort a table by one column and by several columns at once', 'Avoid the sort that reorders one column and leaves the rest behind', 'Explain why sorting never changes the data itself'],
      'Sorting reorders rows. It does not change, add or delete anything, which is why it is safe to use on real data.

The safe way: click any single cell inside your table and then sort. Excel detects the whole range, and the sort applies to complete records, so a row travels together and the amount stays beside its customer.

THE DANGEROUS WAY, and it is a genuinely common disaster: highlighting ONE COLUMN and sorting only that. The values in that column reorder while every other column stays exactly where it was. Your data is now silently, comprehensively wrong — every amount attached to the wrong name — with no error message and often no way to tell by looking. Excel usually offers to "expand the selection", and you should always accept that. Better still, do not select a column at all: click one cell and let Excel find the range.

MULTI-LEVEL SORTING answers questions a single sort cannot. Sort by Region, then by Amount descending, and you get each region''s biggest sale grouped together. Data → Sort lets you add as many levels as you need, and the order of the levels is the order Excel applies them.

If you converted your data to a real Table in the last lesson, this is all easier — the header row carries sort buttons and the range is never ambiguous.',
      'Using your table from the last lesson, sort it three ways: by one text column, by one number column descending, and then a two-level sort (a category first, then an amount). After each sort, pick one row and check that every value in it still belongs together. Then deliberately try the wrong way — select a single column, sort it, and watch what Excel warns you about.',
      '[{"question":"You highlight only the Amount column and sort it descending. What happens?","options":["The amounts reorder but the other columns do not, so rows no longer match","Excel sorts the entire table regardless of what you selected","Nothing — Excel refuses to sort a single column","The column is converted to text"],"correct_index":0},{"question":"You want each region''s largest sale grouped together. What do you use?","options":["A two-level sort: by Region first, then by Amount descending","A single sort by Amount","A single sort by Region","Sorting cannot answer that question"],"correct_index":0}]'::jsonb),
    (v_m1, 'Filtering to See Only What Matters', 'Using filters to narrow a large sheet down to the rows you actually care about, without deleting anything. About 11 minutes.', 'https://www.youtube.com/watch?v=wMlTDXPEjag', 3,
      array['Filter a table to just the rows that matter', 'Use number and date filters beyond simple tick-boxes', 'Recognise when a filter is active, and why leaving one on is risky'],
      'Filtering hides rows. Like sorting, it deletes nothing — the hidden rows are still there and come straight back when you clear the filter.

Turning on filters puts a dropdown in each header. Ticking a few values shows only the matching rows and hides the rest. Your signal that a filter is active is that the ROW NUMBERS JUMP — 1, 4, 9, 14 — instead of running consecutively, and the filter icon in the header changes. Learn to notice both.

Number and date columns get far more than tick-boxes: greater than, less than, between, top 10, above average, this month, last quarter. Text columns get contains, begins with, and does not contain. These are where filtering stops being a convenience and starts answering real questions — "every invoice over 50,000 still unpaid from last quarter" is three filter conditions and no formula at all.

A useful trick: with a filter applied, select the filtered numbers and read the SUM, COUNT and AVERAGE off the status bar at the bottom of the window. That answers most one-off questions without writing anything.

THE HABIT WORTH BUILDING: clear your filters before you walk away or send the file. A filtered sheet looks exactly like a complete sheet to the next person who opens it. That is precisely how people confidently report totals that are missing half the data — and because nothing is broken, nobody catches it.',
      'On your table, answer two questions without deleting a single row. First filter to one category or one month and read the total off the status bar. Then use a number filter — everything above a threshold you choose — and read that total too. Clear both filters and confirm every row is back and the full total matches what you started with.',
      '[{"question":"You filter a sheet to one month and then send the file to a colleague. What is the risk?","options":["It still looks like the complete data to them, so they may report the wrong total","The hidden rows are permanently deleted when the file is saved","Filters cannot be saved inside a file","The formulas stop recalculating"],"correct_index":0},{"question":"Which is a reliable sign that a filter is currently applied?","options":["The row numbers skip instead of running consecutively","The file size increases","The formulas turn red","The header row disappears"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'References, and Why Formulas Break', 'The two things that make beginners give up on formulas: a reference that moves when it shouldn''t, and an error code that looks like gibberish. Both are learnable in an afternoon.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Absolute and Relative References — the $ Anchor', 'What changes and what stays put when you copy a formula, and how the dollar sign controls it. Under 8 minutes, and the single highest-value 8 minutes in this course.', 'https://www.youtube.com/watch?v=FRu48zy-Djk', 1,
      array['Predict how a reference changes when a formula is copied', 'Use $ to lock a column, a row, or both', 'Choose the right reference type for a calculation against a fixed value'],
      'This is the single concept that separates people who fight spreadsheets from people who use them.

Write =B2*C2 in row 2 and copy it down. In row 3 it becomes =B3*C3, in row 4 =B4*C4. Excel adjusted the row automatically. That is a RELATIVE reference, and it is the default — it is the whole reason you write a formula once instead of a thousand times.

Now suppose your VAT rate lives in cell F1 and you write =B2*F1. Copy it down and row 3 becomes =B3*F2 — pointing at an empty cell, because Excel helpfully adjusted a reference you needed to stay still. The results are zeros or nonsense, and there is no error to warn you. This is where most people conclude that Excel is broken.

The fix is $, which means "do not adjust this part":

- F$1 locks the ROW. Copy down and it stays row 1; copy across and the column still moves.
- $F1 locks the COLUMN. Copy across and it stays column F; copy down and the row still moves.
- $F$1 locks BOTH. It always points at F1, wherever you copy it.

So the VAT formula should be =B2*$F$1. Copied down, every row multiplies its own amount by the one rate cell.

The rule of thumb: anything that should change per row stays relative; anything that is a single fixed input — a rate, a target, an exchange rate — gets fully locked.

Pressing F4 while the cursor is on a reference cycles through all four combinations, which is far faster than typing dollar signs by hand.',
      'Build a two-column sheet of item prices, put a single tax rate in one cell off to the side, and write a formula in a third column giving price plus tax. Write it FIRST WITHOUT any dollar signs, copy it down, and look at what breaks — then click into the bottom row and read the formula to see exactly where it is now pointing. Fix it with $ and copy again. Seeing the broken version once is what makes this stick.',
      '[{"question":"=A2*$D$1 is copied from row 2 down to row 5. What does it become?","options":["=A5*$D$1","=A5*$D$4","=A2*$D$1","=A5*D5"],"correct_index":0},{"question":"You need a reference that always points at column B but moves down the rows as you copy downward. Which is it?","options":["$B1","B$1","$B$1","B1"],"correct_index":0}]'::jsonb),
    (v_m2, 'Reading and Fixing Error Values', 'What Excel''s error codes actually mean and how to trace each one back to its cause. About 7 and a half minutes.', 'https://www.youtube.com/watch?v=sFn0gE_y1U4', 2,
      array['Recognise what each common Excel error is telling you', 'Trace an error back to the cell that caused it', 'Fix the cause rather than hiding the symptom'],
      'Excel''s errors are diagnostic messages, not failures. Each one names a different problem, and once you can read them they save you time rather than costing it.

#REF! — the formula points at a cell that no longer exists, almost always because a row or column was deleted out from under it. This one cannot be repaired by editing around it; you have to point it somewhere real again. It is the strongest argument for clearing data rather than deleting whole rows.

#VALUE! — a maths operation hit text. =A1+B1 where B1 contains "n/a", or a number that arrived from a web page as text. Check for stray spaces too: " 500" with a leading space is text as far as Excel is concerned.

#DIV/0! — division by zero or by an empty cell. Common in a "percentage of total" column before the total exists. This is the one case where hiding it is genuinely fine: =IFERROR(A1/B1, "") shows a blank until the denominator is filled in.

#NAME? — Excel does not recognise something you typed. Usually a misspelled function (=SUMM(...)) or text used without quotation marks.

#N/A — a lookup found nothing. In VLOOKUP or XLOOKUP this normally means the value genuinely is not in the list, or it is there but stored differently — text "007" against number 7, or a trailing space.

##### — not an error at all. The column is too narrow to display the number. Widen it.

THE IMPORTANT DISCIPLINE: IFERROR hides an error, it does not fix one. Wrapping a #REF! in IFERROR gives you a clean-looking sheet built on a formula that is still broken, and you will not find out until the numbers matter. Use it only where the error is expected and meaningless, such as a division before the data arrives.',
      'Deliberately break a working sheet four ways: delete a column one of your formulas depends on, type text into a cell being summed, divide by an empty cell, and misspell a function name. Note which error each one produces, then fix each at its cause rather than wrapping it. Doing this on purpose once means you will recognise all four instantly when they turn up for real.',
      '[{"question":"A formula that worked yesterday now shows #REF!. What most likely happened?","options":["A row or column the formula referred to was deleted","The file was renamed or moved","The numbers became too large to calculate","Excel needs to be updated"],"correct_index":0},{"question":"What does wrapping a formula in IFERROR actually do?","options":["Hides the error message without fixing the underlying cause","Repairs the broken cell reference","Forces the sheet to recalculate","Converts text values into numbers"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
